-- +goose Up
-- Office, OpenDocument, text and Keynote files can be presented, so both accepted-type CHECKs list the types the contract accepts.
-- Every previously accepted type stays valid, so the previous release keeps working.
alter table presenting_documents drop constraint presenting_documents_mime_type_check, add constraint presenting_documents_mime_type_check check (mime_type in ('application/pdf', 'image/png', 'image/jpeg', 'image/gif', 'image/webp', 'application/vnd.openxmlformats-officedocument.presentationml.presentation', 'application/vnd.ms-powerpoint', 'application/vnd.oasis.opendocument.presentation', 'application/vnd.openxmlformats-officedocument.wordprocessingml.document', 'application/msword', 'application/vnd.oasis.opendocument.text', 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet', 'application/vnd.ms-excel', 'application/vnd.oasis.opendocument.spreadsheet', 'text/plain', 'application/vnd.apple.keynote', 'application/x-iwork-keynote-sffkey'));
alter table sync_chat_attachments drop constraint sync_chat_attachments_mime_type_check1, add constraint sync_chat_attachments_mime_type_check1 check (mime_type in ('image/png', 'image/jpeg', 'image/gif', 'image/webp', 'application/pdf', 'text/plain', 'application/msword', 'application/vnd.openxmlformats-officedocument.wordprocessingml.document', 'application/vnd.ms-excel', 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet', 'application/vnd.ms-powerpoint', 'application/vnd.openxmlformats-officedocument.presentationml.presentation', 'application/vnd.oasis.opendocument.text', 'application/vnd.oasis.opendocument.spreadsheet', 'application/vnd.oasis.opendocument.presentation', 'application/vnd.apple.keynote', 'application/x-iwork-keynote-sffkey'));

-- +goose Down
-- The narrower CHECKs are restored without validating rows that already hold a wider type.
alter table sync_chat_attachments drop constraint sync_chat_attachments_mime_type_check1, add constraint sync_chat_attachments_mime_type_check1 check (mime_type in ('image/png', 'image/jpeg', 'image/gif', 'image/webp', 'application/pdf', 'text/plain', 'application/msword', 'application/vnd.openxmlformats-officedocument.wordprocessingml.document', 'application/vnd.ms-excel', 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet', 'application/vnd.ms-powerpoint', 'application/vnd.openxmlformats-officedocument.presentationml.presentation', 'application/vnd.oasis.opendocument.text', 'application/vnd.oasis.opendocument.spreadsheet', 'application/vnd.oasis.opendocument.presentation')) not valid;
alter table presenting_documents drop constraint presenting_documents_mime_type_check, add constraint presenting_documents_mime_type_check check (mime_type in ('application/pdf', 'image/png', 'image/jpeg', 'image/gif', 'image/webp')) not valid;
